        SQ = function(vX, vY)
            local Type = vY.Type
            if Type == "Toggle" then
                return { idx = vX, type = "Toggle", value = vY.Value == true }
            elseif Type == "Slider" then
                return { idx = vX, type = "Slider", value = tostring(vY.Value) }
            elseif Type == "Dropdown" then
